/** @jest-environment node */

const { buildQueryString } = require('../buildQueryString');

describe('buildQueryString', () => {
  it('serializes array tag ids and query params', () => {
    const query = buildQueryString({
      requestedTagIds: ['tag-1', 'tag-2'],
      queryParams: { app: 'app-id' },
    });

    expect(query).toContain('requestedTagIds=%5B%22tag-1%22%2C%22tag-2%22%5D');
    expect(query).toContain('app=app-id');
  });

  it('parses comma-separated tag ids', () => {
    const query = buildQueryString({
      requestedTagIds: 'tag-1, tag-2',
    });

    expect(query).toContain('tag-1');
    expect(query).toContain('tag-2');
  });

  it('skips duplicate requestedTagIds in queryParams', () => {
    const query = buildQueryString({
      requestedTagIds: ['tag-1'],
      queryParams: { requestedTagIds: 'ignored', app: 'app-id' },
    });

    expect(query).toContain('app=app-id');
    expect(query.match(/requestedTagIds/g)).toHaveLength(1);
  });

  it('returns empty string when config has no params', () => {
    expect(buildQueryString({})).toBe('');
  });

  it('merges TRANSLATIONS_ADDITIONAL_TAG_IDS from env and deduplicates', () => {
    process.env.TRANSLATIONS_ADDITIONAL_TAG_IDS = 'shared-tag, mfe-tag';
    const query = buildQueryString({
      requestedTagIds: ['mfe-tag'],
      queryParams: { app: 'app-id' },
    });
    delete process.env.TRANSLATIONS_ADDITIONAL_TAG_IDS;

    expect(query).toContain('mfe-tag');
    expect(query).toContain('shared-tag');
    expect(query.match(/mfe-tag/g)).toHaveLength(1);
  });
});
